/* Catalogo y ubicaciones publicas LumiStore. No contiene clientes, usuarios ni ventas. Ejecutar una sola vez sobre lumistore vacia. */
SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() <> N'lumistore' THROW 51000, 'Base incorrecta: lumistore requerida.', 1;
